/// A named peak above 7,000 m in Nepal.
class Peak {
  /// Unique peak identifier (e.g. `pk-everest`).
  final String id;

  /// English name.
  final String nameEn;

  /// Nepali name in Devanagari, or null if not attested.
  final String? nameNe;

  /// Name status: `attested`, `transliterated`, or `pending`.
  final String nameStatus;

  /// Source for Nepali name, if any.
  final String? nameNeSource;

  /// Elevation in metres.
  final double elevation;

  /// Prominence in metres, if known.
  final double? prominence;

  /// Mountain range, if known.
  final String? range;

  /// Massif, if known.
  final String? massif;

  /// Peak class: `eight_thousander_main`, `eight_thousander_official_additional`, `seven_thousander`.
  final String peakClass;

  /// Nepal share: `inside` or `border`.
  final String nepalShare;

  /// Border countries, if any.
  final List<String>? borderCountries;

  /// Province codes (CBS), e.g. `[1]` for Koshi.
  final List<int> provinceCodes;

  /// District codes (CBS), e.g. `[103]` for Solukhumbu.
  final List<int> districtCodes;

  /// Longitude in degrees.
  final double lng;

  /// Latitude in degrees.
  final double lat;

  /// Coordinate source ID, e.g. `S04`.
  final String coordSource;

  /// Coordinate accuracy in metres, if known.
  final int? coordAccuracyM;

  /// Official eight-thousander list reference, if any.
  final String? officialList;

  /// First ascent year, if known.
  final int? firstAscentYear;

  /// Review status: `approved` or `draft`.
  final String reviewStatus;

  /// English aliases, if any.
  final List<String>? aliasesEn;

  /// Notes in English, if any.
  final String? notesEn;

  const Peak({
    required this.id,
    required this.nameEn,
    this.nameNe,
    required this.nameStatus,
    this.nameNeSource,
    required this.elevation,
    this.prominence,
    this.range,
    this.massif,
    required this.peakClass,
    required this.nepalShare,
    this.borderCountries,
    required this.provinceCodes,
    required this.districtCodes,
    required this.lng,
    required this.lat,
    required this.coordSource,
    this.coordAccuracyM,
    this.officialList,
    this.firstAscentYear,
    required this.reviewStatus,
    this.aliasesEn,
    this.notesEn,
  });

  /// Whether this peak is on Nepal's border.
  bool get isBorderPeak => nepalShare == 'border';

  /// Whether this peak is a main eight-thousander.
  bool get isMainEightThousander => peakClass == 'eight_thousander_main';

  /// Whether this peak is an official additional eight-thousander.
  bool get isOfficialAdditionalEightThousander =>
      peakClass == 'eight_thousander_official_additional';

  /// Whether this peak is a seven-thousander.
  bool get isSevenThousander => peakClass == 'seven_thousander';
}

